def get_wallet_summary(db: Session = Depends(get_db)):
    summary = wallet_service.get_wallet_summary(db)
    return summary

def get_transactions(
    db: Session,
    transaction_type: Optional[str] = None,
    limit: Optional[int] = None
) -> List[Transaction]:
    query = db.query(Transaction).order_by(Transaction.created_at.desc())

    all_transactions = query.all()

    if limit and len(all_transactions) > limit:
        all_transactions = all_transactions[:limit]

    if transaction_type:
        all_transactions = [t for t in all_transactions if t.type == transaction_type]

    return all_transactions

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()
